  NutrientTransparencyData _preWorkoutFluidTransparency({
    required MacroTargets macroTargets,
    required double bodyWeightKg,
    bool useImperial = false,
  }) {
    final pre = macroTargets.preRun;
    final fluidsMl = pre.fluidsMl.round();
    final rangeLowMl = pre.fluidsLowMl?.round() ?? (fluidsMl * 0.8).round();
    final rangeHighMl = pre.fluidsHighMl?.round() ?? (fluidsMl * 1.2).round();

    // Determine tier from time (estimate from fluid value: 250mL = Tier 2, BW-based = Tier 1)
    // Tier 3 = 0 ml, Tier 2 = ~250 ml, Tier 1 = BW * 5–7 ml
    final isTier3 = fluidsMl == 0;
    final isTier2 = !isTier3 && (fluidsMl <= 300);
    final String blurb;
    final List<FormulaLine> tldrLines;

    if (isTier3) {
      blurb = 'Too late for structured pre-hydration. A few small sips are fine '
          'for comfort, but fluid taken now won\'t absorb before exercise begins. '
          'Focus on the during-workout plan instead.';
      tldrLines = const [];
    } else if (isTier2) {
      blurb = 'Not enough time for the full protocol. 250 ml is all that can '
          'meaningfully absorb before exercise begins. Sip it steadily \u2014 '
          'don\'t chug it just before you start.';
      tldrLines = [
        FormulaLine([
          fAccent('fixed top-up '),
          fOp('= '),
          fResult('${fluidsMl}mL'),
        ]),
      ];
    } else {
      blurb = 'The goal before a workout is to start **euhydrated** \u2014 at your '
          'normal baseline, not loaded or depleted. With enough time available, '
          'you have time for the full protocol: sip ${fluidsMl}mL gradually, let '
          'it absorb, and aim for pale yellow urine before you head out.';
      final mlPerKg = bodyWeightKg > 0
          ? (fluidsMl / bodyWeightKg).toStringAsFixed(1)
          : '6.0';
      tldrLines = [
        FormulaLine([
          fAccent('body weight '),
          fOp('\u00d7 '),
          fAccent('${mlPerKg} mL/kg '),
          fOp('= '),
          fResult('${fluidsMl}mL'),
        ]),
      ];
    }

    return NutrientTransparencyData(
      nutrientLabel: 'Fluids',
      nutrientColor: const Color(0xFF4A9EFF), // blue
      primaryUnit: useImperial ? 'oz' : 'mL',
      phase: 'before',
      tldrBody: blurb,
      tldrLines: tldrLines,
      storySections: _preWorkoutFluidStorySections(isTier3: isTier3),
      calculationSections: _buildPreWorkoutFluidCalculationSections(
        bodyWeightKg: bodyWeightKg,
        fluidsMl: fluidsMl,
        fluidsLowMl: rangeLowMl,
        fluidsHighMl: rangeHighMl,
      ),
      videoTitle: 'Watch: Pre-Workout Hydration',
      targetGrams: fluidsMl.toDouble(),
      rangeLow: rangeLowMl.toDouble(),
      rangeHigh: rangeHighMl.toDouble(),
      sportLabel: 'Pre-Workout',
    );
  }

