  /// Builds the fluid [Map<Scenario, NutrientTransparencyData>] for a
  /// single-sport (non-brick) during workout.
  Map<Scenario, NutrientTransparencyData> _singleSportFluidMap({
    required MacroTargets macroTargets,
    required double bodyWeightKg,
    bool useImperial = false,
  }) {
    final during = macroTargets.duringRun;
    final durationMin = macroTargets.metrics.durationMin.round();
    final isTested = during.isTested;
    final shortWorkoutGate = durationMin < 60 &&
        (during.tempC == null || (during.tempC ?? 25) < 30);

    final map = <Scenario, NutrientTransparencyData>{};

    // Single sport is always present
    map[Scenario.singleSport] = _duringSingleSportFluidTransparency(
      macroTargets: macroTargets,
      bodyWeightKg: bodyWeightKg,
      useImperial: useImperial,
    );

    // Short workout gate — different blurb, same numbers
    if (shortWorkoutGate) {
      map[Scenario.shortWorkout] = _shortWorkoutFluidTransparency(
        macroTargets: macroTargets,
        useImperial: useImperial,
      );
    }

    // Known-rate — different blurb emphasising the tested override
    if (isTested) {
      map[Scenario.knownRate] = _knownRateFluidTransparency(
        macroTargets: macroTargets,
        bodyWeightKg: bodyWeightKg,
        useImperial: useImperial,
      );
    }

    return map;
  }

  /// Builds the fluid [Map<Scenario, NutrientTransparencyData>] for a
  /// brick/tri segment (non-swim) during workout.
  Map<Scenario, NutrientTransparencyData> _brickSegmentFluidMap({
    required MacroTargets macroTargets,
    required BrickSegmentMacroTarget segment,
    required double bodyWeightKg,
    bool useImperial = false,
  }) {
    final isTested = segment.isTested;
    final hasRedistribution = [
      ...macroTargets.duringRun.safetyFlags,
      ...segment.safetyFlags,
    ].any((f) => f.toLowerCase().contains('redistri'));

    final map = <Scenario, NutrientTransparencyData>{};

    // Multi-segment is always present for bricks
    map[Scenario.multiSegment] = _brickSegmentFluidTransparency(
      macroTargets: macroTargets,
      segment: segment,
      bodyWeightKg: bodyWeightKg,
      useImperial: useImperial,
    );

    // Redistribution — only when run leg hit GI ceiling
    if (hasRedistribution) {
      map[Scenario.redistribution] = _redistributionFluidTransparency(
        macroTargets: macroTargets,
        segment: segment,
        bodyWeightKg: bodyWeightKg,
        useImperial: useImperial,
      );
    }

    // Known-rate
    if (isTested) {
      map[Scenario.knownRate] = _knownRateFluidTransparency(
        macroTargets: macroTargets,
        bodyWeightKg: 0, // weight not shown in brick-segment known-rate blurb
        useImperial: useImperial,
        forBrickSegment: segment,
      );
    }

    return map;
  }

