  // ---------------------------------------------------------------------------
  // CALCULATION SECTION BUILDERS — step-by-step breakdown for the UI accordion
  //
  // The edge function already performs all these calculations, but for the
  // transparency UI we recompute the intermediate multipliers so we can
  // display them as numbered steps. Derivation is:
  //   effective = base × temp_mult × humidity_mult × indoor_mult  (clamped)
  //   base = effective / (temp_mult × humidity_mult × indoor_mult)
  // ---------------------------------------------------------------------------

  NutrientTransparencyData _duringSingleSportFluidTransparency({
    required MacroTargets macroTargets,
    required double bodyWeightKg,
    bool useImperial = false,
  }) {
    final during = macroTargets.duringRun;
    final durationH = macroTargets.metrics.durationH;
    final durationMin = macroTargets.metrics.durationMin.round();
    final fluidRateMlH = during.fluidRateMlPerH.round();
    final fluidTotalMl = during.fluidTotalMl.round();

    // Use derivation fields if available (new plans); fall back gracefully
    final effectiveSweatRate = during.effectiveSweatRateLPerH;
    final replacementPct = during.replacementPercent;
    final floorMlH = during.floorMlPerH;
    final ceilingMlH = during.ceilingMlPerH;
    final safetyFlags = during.safetyFlags;
    final isTested = during.isTested;

    final shortWorkoutGate = durationMin < 60 &&
        (during.tempC == null || (during.tempC ?? 25) < 30);

    final List<FormulaLine> tldrLines;
    final String blurb;

    if (shortWorkoutGate && fluidRateMlH < 200) {
      // Short-workout gate
      blurb =
          'This workout is short and conditions are mild \u2014 no structured '
          'hydration plan needed. **Drink to thirst.** If you want a number, '
          'aim for no more than 10 oz. Don\'t exceed 20 oz.';
      tldrLines = [
        FormulaLine([
          fAccent('short gate '),
          fOp('= '),
          fAccent('duration < 60 min + mild temp '),
          fOp('\u2192 '),
          fDim('drink to thirst'),
        ]),
      ];
    } else if (effectiveSweatRate != null && replacementPct != null) {
      // New derivation fields available
      blurb =
          'Your fluid target starts with a duration-based replacement strategy, '
          'then two overrides are applied: a **floor** that raises the target if '
          'needed to keep you within 2% body weight loss, and a **ceiling** that '
          'caps it at what your gut can absorb and what\'s safe for blood sodium. '
          'The final recommendation is always between those two bounds.';

      final replacePctPct = (replacementPct * 100).round();
      final ceilNote = ceilingMlH != null
          ? '${ceilingMlH} mL/hr'
          : 'GI ceiling';
      final floorNote = floorMlH != null ? '${floorMlH} mL/hr' : '2% BW floor';

      tldrLines = [
        FormulaLine([
          fAccent('${durationMin} min '),
          fOp('\u2192 '),
          fAccent('replacement '),
          fDim('${replacePctPct}%'),
        ], stepNumber: '\u2460'),
        FormulaLine([
          fAccent('sweat rate '),
          fDim('${effectiveSweatRate.toStringAsFixed(2)} L/hr '),
          fOp('\u00d7 '),
          fAccent('${replacePctPct}% '),
          fOp('= '),
          fDim('${fluidRateMlH} mL/hr'),
        ], stepNumber: '\u2461'),
        if (floorMlH != null)
          FormulaLine([
            fOp('\u2193 '),
            fAccent('floor '),
            fDim(floorNote),
            fOp(' (2% BW deficit)'),
          ], stepNumber: '\u2462'),
        if (ceilingMlH != null)
          FormulaLine([
            fOp('\u2191 '),
            fAccent('ceiling '),
            fDim(ceilNote),
            fOp(' (GI limit)'),
          ], stepNumber: '\u2463'),
        if (safetyFlags.isNotEmpty)
          FormulaLine([
            fOp('\u2713 '),
            fAccent('safety '),
            fDim(safetyFlags.first),
          ]),
        FormulaLine(
          [
            fAccent('$fluidRateMlH mL/hr '),
            fOp('\u00d7 '),
            fAccent('${_formatDuration(durationH)} hr '),
            fOp('= '),
            fResult('${fluidTotalMl}mL'),
          ],
          isResultLine: true,
          showDividerBefore: true,
        ),
      ];
    } else {
      // Legacy plan — simple card
      blurb =
          'Your fluid target replaces a portion of your sweat losses during '
          'activity, keeping you within a safe hydration window.';
      tldrLines = [
        FormulaLine([
          fAccent('${fluidRateMlH} mL/hr '),
          fOp('\u00d7 '),
          fAccent('${_formatDuration(durationH)} hr '),
          fOp('= '),
          fResult('${fluidTotalMl}mL'),
        ], isResultLine: true),
      ];
    }

    final fluidsLowMl = during.fluidsLowMl;
    final fluidsHighMl = during.fluidsHighMl;

    final calcSections = _buildDuringFluidCalculationSections(
      during: during,
      durationMin: durationMin,
      durationH: durationH,
      bodyWeightKg: bodyWeightKg,
    );

    return NutrientTransparencyData(
      nutrientLabel: 'Fluids',
      nutrientColor: const Color(0xFF4A9EFF),
      primaryUnit: useImperial ? 'oz/hr' : 'mL/hr',
      phase: 'during',
      isTested: isTested,
      tldrBody: blurb,
      tldrLines: tldrLines,
      calculationSections: calcSections,
      calculationWarning: safetyFlags.isNotEmpty ? safetyFlags.first : null,
      storySections: _duringFluidStorySections(
        isTested: isTested,
        shortWorkoutGate: shortWorkoutGate,
        hasDerivationFields: effectiveSweatRate != null,
      ),
      videoTitle: 'Watch: Hydration Strategy',
      targetGrams: fluidTotalMl.toDouble(),
      rangeLow: fluidsLowMl,
      rangeHigh: fluidsHighMl,
      sportLabel: null,
    );
  }

  List<StorySection> _duringFluidStorySections({
    required bool isTested,
    required bool shortWorkoutGate,
    required bool hasDerivationFields,
  }) {
    return [
      if (shortWorkoutGate)
        const StorySection(
          question: 'Why "drink to thirst" for short workouts?',
          answer:
              'For efforts under 60 minutes in mild conditions, the body\'s thirst '
              'mechanism is an accurate guide. You cannot meaningfully deplete '
              'hydration status in that time window under normal temperatures.',
          citation: 'Noakes (2012) \u2014 Hyponatremia in endurance sports',
          dataChips: ['Short gate \u00b7 < 60 min + temp < 30\u00b0C'],
        ),
      const StorySection(
        question: 'Why replace a percentage of sweat losses, not all of it?',
        answer:
            'Replacing 100% of sweat losses during exercise can lead to '
            '**hyponatremia** (dangerously low blood sodium) by diluting the '
            'sodium remaining in your blood. Research shows 50\u201380% replacement '
            'is optimal, scaled up with event duration.',
        citation: 'Baker (2017) \u2014 Journal of the International Society of Sports Nutrition',
        dataChips: [
          '<60 min \u00b7 30%',
          '60\u201390 min \u00b7 50%',
          '90\u2013150 min \u00b7 60%',
          '150\u2013240 min \u00b7 70%',
          '240+ min \u00b7 80%',
        ],
      ),
      const StorySection(
        question: 'What is the 2% body weight floor?',
        answer:
            'Losing more than 2% of body weight through sweat starts to impair '
            'performance. The floor ensures your recommended rate is high enough '
            'to stay within that safety boundary, **even if the replacement % alone '
            'would leave you too depleted.**',
        citation: 'Sawka et al. (2007) \u2014 ACSM Position Stand',
        dataChips: ['>2% BW deficit \u00b7 performance impact', '>3% BW deficit \u00b7 significant risk'],
      ),
      const StorySection(
        question: 'What is the GI ceiling?',
        answer:
            'Your gut can only absorb so much fluid per hour. Drinking above '
            'the ceiling causes GI distress without improving hydration. '
            'Running\'s mechanical impact restricts absorption more than cycling.',
        citation: 'Pfeiffer et al. (2012) \u2014 GI Problems in Endurance Sports',
        dataChips: [
          'Run \u00b7 max 800 mL/hr',
          'Bike \u00b7 max 1200 mL/hr',
        ],
      ),
      StorySection(
        question: 'What\'s my actual sweat rate?',
        answer: isTested
            ? 'Your sweat rate is from a **personal sweat test** \u2014 the most '
                'accurate input available. This rate already accounts for your '
                'individual physiology. If conditions differ significantly from your '
                'test conditions, consider retesting.'
            : 'Your sweat rate is estimated from your sweat profile category and '
                'adjusted for temperature, humidity, and indoor conditions. '
                'For a more accurate number, weigh yourself nude before and after '
                'a known-duration workout and enter the result below.',
        citation: isTested
            ? null
            : 'Precision Fuel & Hydration / TrainingPeaks \u2014 standard at-home sweat test protocol',
        inlineEditType: InlineEditType.knownSweatRate,
        dataChips: isTested
            ? ['TESTED \u2713 \u00b7 personal sweat test']
            : [
                'Light \u00b7 0.90 L/hr',
                'Medium \u00b7 1.28 L/hr',
                'Heavy \u00b7 1.66 L/hr',
              ],
      ),
    ];
  }

  // ---------------------------------------------------------------------------
  // BRICK SEGMENT FLUID
  // ---------------------------------------------------------------------------

  NutrientTransparencyData _brickSegmentFluidTransparency({
    required MacroTargets macroTargets,
    required BrickSegmentMacroTarget segment,
    required double bodyWeightKg,
    bool useImperial = false,
  }) {
    final segmentSport = segment.sport;
    final durationMin = segment.durationMinutes;
    final durationH = durationMin / 60.0;
    final totalEventMin = macroTargets.metrics.durationMin.round();

    // Segment water total
    final waterMl = segment.waterMl.round();

    // Derivation fields (segment level if available)
    final effectiveSweatRate = segment.effectiveSweatRateLPerH;
    final replacementPct = segment.replacementPercent;
    final floorMlH = segment.floorMlPerH;
    final ceilingMlH = segment.ceilingMlPerH;
    final isTested = segment.isTested;

    // Rate from segment totals
    final fluidRateMlH = durationH > 0
        ? (waterMl / durationH).round()
        : 0;

    final List<FormulaLine> tldrLines;
    final String blurb =
        'In a race or brick, the replacement strategy is based on '
        '**total event duration** \u2014 not just this leg. When the run leg '
        'can\'t absorb enough to stay within 2% body weight loss, the shortfall '
        'is redistributed here where your gut has more capacity.';

    if (effectiveSweatRate != null && replacementPct != null) {
      final replacePctPct = (replacementPct * 100).round();
      tldrLines = [
        FormulaLine([
          fAccent('total event '),
          fDim('${totalEventMin} min '),
          fOp('\u2192 '),
          fAccent('replacement '),
          fDim('${replacePctPct}%'),
        ], stepNumber: '\u2460'),
        FormulaLine([
          fAccent('sweat rate '),
          fDim('${effectiveSweatRate.toStringAsFixed(2)} L/hr '),
          fOp('\u00d7 '),
          fAccent('${replacePctPct}% '),
          fOp('= '),
          fDim('$fluidRateMlH mL/hr'),
        ], stepNumber: '\u2461'),
        if (floorMlH != null)
          FormulaLine([
            fOp('\u2193 '),
            fAccent('floor '),
            fDim('$floorMlH mL/hr'),
          ], stepNumber: '\u2462'),
        if (ceilingMlH != null)
          FormulaLine([
            fOp('\u2191 '),
            fAccent('ceiling '),
            fDim('$ceilingMlH mL/hr '),
            fOp('(${segmentSport} limit)'),
          ], stepNumber: '\u2463'),
        FormulaLine(
          [
            fAccent('$fluidRateMlH mL/hr '),
            fOp('\u00d7 '),
            fAccent('${_formatDuration(durationH)} hr '),
            fOp('= '),
            fResult('${waterMl}mL'),
          ],
          isResultLine: true,
          showDividerBefore: true,
        ),
      ];
    } else {
      // Legacy fallback
      tldrLines = [
        FormulaLine([
          fAccent('$fluidRateMlH mL/hr '),
          fOp('\u00d7 '),
          fAccent('${_formatDuration(durationH)} hr '),
          fOp('= '),
          fResult('${waterMl}mL'),
        ], isResultLine: true),
      ];
    }

    return NutrientTransparencyData(
      nutrientLabel: 'Fluids',
      nutrientColor: const Color(0xFF4A9EFF),
      primaryUnit: useImperial ? 'oz/hr' : 'mL/hr',
      phase: 'during',
      isTested: isTested,
      tldrBody: blurb,
      tldrLines: tldrLines,
      calculationSections: _buildBrickFluidCalculationSections(
        during: macroTargets.duringRun,
        segment: segment,
        totalEventMin: totalEventMin,
        bodyWeightKg: bodyWeightKg,
      ),
      calculationWarning: segment.safetyFlags.isNotEmpty
          ? segment.safetyFlags.first
          : null,
      storySections: _duringFluidStorySections(
        isTested: isTested,
        shortWorkoutGate: false,
        hasDerivationFields: effectiveSweatRate != null,
      ),
      videoTitle: 'Watch: Hydration Strategy',
      targetGrams: waterMl.toDouble(),
      rangeLow: segment.waterLowMl,
      rangeHigh: segment.waterHighMl,
      sportLabel: segmentSport,
    );
  }

