  /// Public accessor so the sheet can request the swim zero-state directly
  /// without going through the map-returning [getFluidTransparencyData].
  NutrientTransparencyData _swimFluidTransparency() {
    return NutrientTransparencyData(
      nutrientLabel: 'Fluids',
      nutrientColor: const Color(0xFF4A9EFF),
      primaryUnit: 'mL/hr',
      phase: 'during',
      tldrBody:
          'No drinking during swim \u2014 T1 covers the deficit. '
          'Your sweat losses during the swim are accounted for in the '
          'total-event fluid budget and distributed across the bike and '
          'T1 transition windows.',
      tldrLines: const [],
      storySections: const [
        StorySection(
          question: 'Why no drinking during swim?',
          answer:
              'It is physically impossible to drink during an open-water or pool '
              'swim without stopping. Sweat losses during swimming are also lower '
              '(~0.4\u00d7 land sports) due to water cooling the skin. '
              'The fluid deficit from the swim is fully accounted for in the '
              'T1 transition and subsequent bike segment targets.',
          citation: 'Maughan & Shirreffs (2004) \u2014 swimming thermoregulation',
          dataChips: ['Swim sweat modifier \u00b7 0.4\u00d7 land sports'],
        ),
        StorySection(
          question: 'What covers the swim deficit?',
          answer:
              'T1 transition provides a fixed 300 mL bolus timed for what you can '
              'comfortably take in during a 2\u20135 minute transition stop. The bike '
              'leg then carries the remainder of the total-event fluid budget.',
          dataChips: ['T1 bolus \u00b7 300 mL fixed'],
        ),
      ],
      isSwimZero: true,
      swimCallout: 'Fluid deficit covered by: T1 transition \u00b7 Bike segment',
      targetGrams: 0,
      rangeLow: 0,
      rangeHigh: 0,
      sportLabel: 'Swim',
    );
  }

  // ---------------------------------------------------------------------------
  // TRANSITION FLUID
  // ---------------------------------------------------------------------------

  NutrientTransparencyData _transitionFluidTransparency({
    required ExplanationPhase phase,
    required MacroTargets macroTargets,
  }) {
    final isT1 = phase == ExplanationPhase.transition1;
    final transitionName = isT1 ? 'T1' : 'T2';

    final transitions = macroTargets.brickPhaseTargets?.transitions;
    final tIdx = isT1 ? 0 : 1;
    final transition = (transitions != null && tIdx < transitions.length)
        ? transitions[tIdx]
        : null;
    final waterMl = transition?.waterMl.round() ?? 300;
    final isTested = transition?.isTested ?? false;

    return NutrientTransparencyData(
      nutrientLabel: 'Fluids',
      nutrientColor: const Color(0xFF4A9EFF),
      primaryUnit: 'mL',
      phase: 'transition',
      isTested: isTested,
      tldrBody:
          'Transitions are brief, fixed hydration windows \u2014 not a '
          'calculated segment. The 300 mL target isn\'t derived from your sweat '
          'rate; it\'s a conservative bolus sized for what you can comfortably '
          'take in during a 2\u20135 minute stop. **$transitionName** '
          '${isT1 ? "bridges the swim gap and offsets wetsuit heat." : "is your last easy opportunity before running GI tolerance drops."}',
      tldrLines: [
        FormulaLine([
          fAccent('$transitionName '),
          fOp('= '),
          fAccent('fixed 300 mL '),
          fOp('\u2192 '),
          fResult('${waterMl}mL'),
        ]),
      ],
      calculationSections:
          _buildTransitionFluidCalculationSections(waterMl: waterMl),
      storySections: [
        StorySection(
          question: 'Why is the transition fluid fixed at 300 mL?',
          answer:
              'Transition windows are too short to calculate a precise sweat-rate-based '
              'target. 300 mL is a conservative bolus sized to what most athletes can '
              'comfortably consume and absorb during a 2\u20135 minute stop without '
              'causing GI distress when movement resumes.',
          citation: 'Consensus recommendation \u2014 USA Triathlon / ITU nutrition guidelines',
          dataChips: ['T1/T2 fixed \u00b7 300 mL', 'Confidence \u00b7 LOW'],
        ),
      ],
      targetGrams: waterMl.toDouble(),
      rangeLow: transition?.waterLowMl,
      rangeHigh: transition?.waterHighMl,
      sportLabel: transitionName,
    );
  }

